\u89E3\u8BFB\uFF1A\u5F00\u7BC7\u5373\u70B9\u660E\u6089\u8FBE\u591A\u7684\u7CBE\u795E\u56F0\u5883\u2014\u2014\u5916\u5728\u7684\u5B97\u6559\u89C4\u8303\u4E0E\u77E5\u8BC6\u65E0\u6CD5\u6EE1\u8DB3\u5185\u5728\u5BF9\u771F\u7406\u7684\u6E34\u6C42\uFF0C\u9884\u793A\u4ED6\u5C06\u8D70\u4E0A\u4E00\u6761\u72EC\u7ACB\u63A2\u7D22\u4E4B\u8DEF\u3002

\u7B2C\u4E8C\u7AE0\uFF1A\u4E0E\u6C99\u95E8\u540C\u884C
\u4E3B\u8981\u89C2\u70B9\uFF1A\u6089\u8FBE\u591A\u79BB\u5F00\u5BB6\u5EAD\uFF0C\u52A0\u5165\u82E6\u884C\u50E7\uFF08\u6C99\u95E8\uFF09\u884C\u5217\uFF0C\u8BD5\u56FE\u901A\u8FC7\u7981\u6B32\u3001\u5FCD\u8010\u548C\u5426\u5B9A\u8089\u4F53\u6765\u63A5\u8FD1\u771F\u7406\u3002
\u91CD\u8981\u6BB5\u843D\uFF1A\u201C\u4ED6\u5B66\u4F1A\u4E86\u5FCD\u53D7\u9965\u997F\u3001\u75BC\u75DB\u3001\u7126\u6E34\u3001\u75B2\u5026\u2026\u2026\u4F46\u4ED6\u77E5\u9053\uFF0C\u8FD9\u4E9B\u53EA\u662F\u9003\u907F\u2018\u6211\u2019\u7684\u65B9\u5F0F\uFF0C\u5E76\u975E\u901A\u5411\u2018\u6211\u2019\u7684\u9053\u8DEF\u3002\u201D
\u89E3\u8BFB\uFF1A\u82E6\u884C\u867D\u80FD\u78E8\u70BC\u610F\u5FD7\uFF0C\u5374\u65E0\u6CD5\u5E26\u6765\u7EC8\u6781\u89C9\u609F\u3002\u6089\u8FBE\u591A\u610F\u8BC6\u5230\uFF0C\u5426\u5B9A\u611F\u5B98\u4E16\u754C\u5E76\u4E0D\u80FD\u62B5\u8FBE\u771F\u5B9E\uFF0C\u53CD\u800C\u53EF\u80FD\u9677\u5165\u53E6\u4E00\u79CD\u6267\u5FF5\u3002

\u7B2C\u4E09\u7AE0\uFF1A\u4E54\u8FBE\u6469\uFF08\u4F5B\u9640\uFF09
\u4E3B\u8981\u89C2\u70B9\uFF1A\u6089\u8FBE\u591A\u9047\u89C1\u5DF2\u89C9\u609F\u7684\u4E54\u8FBE\u6469\uFF08\u4F5B\u9640\uFF09\uFF0C\u656C\u4F69\u5176\u5B81\u9759\u4E0E\u667A\u6167\uFF0C\u4F46\u62D2\u7EDD\u7688\u4F9D\u5176\u6559\u4E49\u3002
\u91CD\u8981\u6BB5\u843D\uFF1A\u201C\u6CA1\u6709\u4EBA\u80FD\u901A\u8FC7\u6559\u4E49\u83B7\u5F97\u6551\u8D4E\u2026\u2026\u77E5\u8BC6\u53EF\u4EE5\u4F20\u6388\uFF0C\u4F46\u667A\u6167\u4E0D\u80FD\u3002\u201D
\u89E3\u8BFB\uFF1A\u9ED1\u585E\u501F\u6089\u8FBE\u591A\u4E4B\u53E3\u5F3A\u8C03\uFF1A\u771F\u7406\u5FC5\u987B\u4EB2\u5386\uFF0C\u4E0D\u53EF\u9760\u4ED6\u4EBA\u8A00\u8BF4\u83B7\u5F97\u3002\u8FD9\u662F\u5BF9\u5236\u5EA6\u5316\u5B97\u6559\u7684\u6279\u5224\uFF0C\u4E5F\u662F\u5BF9\u4E2A\u4F53\u89C9\u9192\u7684\u80AF\u5B9A\u3002

\u7B2C\u56DB\u7AE0\uFF1A\u89C9\u9192
\u4E3B\u8981\u89C2\u70B9\uFF1A\u6089\u8FBE\u591A\u51B3\u5B9A\u72EC\u81EA\u4E0A\u8DEF\uFF0C\u4E0D\u518D\u8FFD\u968F\u4EFB\u4F55\u5BFC\u5E08\uFF0C\u51B3\u5FC3\u201C\u6210\u4E3A\u81EA\u5DF1\u201D\u3002
\u91CD\u8981\u6BB5\u843D\uFF1A\u201C\u6211\u552F\u4E00\u8981\u505A\u7684\u4E8B\uFF0C\u662F\u503E\u542C\u5185\u5FC3\u7684\u58F0\u97F3\uFF0C\u800C\u4E0D\u662F\u542C\u4ECE\u5916\u754C\u7684\u547D\u4EE4\u3002\u201D
\u89E3\u8BFB\uFF1A\u8FD9\u662F\u5168\u4E66\u8F6C\u6298\u70B9\u2014\u2014\u4ECE\u5411\u5916\u6C42\u7D22\u8F6C\u5411\u5411\u5185\u63A2\u5BFB\u3002\u201C\u81EA\u6211\u201D\u6210\u4E3A\u4FEE\u884C\u7684\u6838\u5FC3\u5BF9\u8C61\u3002

\u7B2C\u4E94\u7AE0\uFF1A\u5361\u739B\u62C9\uFF08Kamala\uFF09
\u4E3B\u8981\u89C2\u70B9\uFF1A\u6089\u8FBE\u591A\u8FDB\u5165\u4E16\u4FD7\u4E16\u754C\uFF0C\u5411\u540D\u5993\u5361\u739B\u62C9\u5B66\u4E60\u7231\u7684\u827A\u672F\uFF0C\u5E76\u7ACB\u5FD7\u6210\u4E3A\u5BCC\u5546\u3002
\u91CD\u8981\u6BB5\u843D\uFF1A\u201C\u6211\u8981\u5B66\u4F1A\u505A\u751F\u610F\uFF0C\u6211\u8981\u79EF\u805A\u8D22\u5BCC\uFF0C\u6211\u8981\u4EAB\u53D7\u611F\u5B98\u4E4B\u4E50\u2014\u2014\u56E0\u4E3A\u8FD9\u662F\u6211\u5C1A\u672A\u4F53\u9A8C\u7684\u751F\u6D3B\u3002\u201D
\u89E3\u8BFB\uFF1A\u6089\u8FBE\u591A\u4E3B\u52A8\u62E5\u62B1\u201C\u8F6E\u56DE\u201D\uFF08Samsara\uFF09\uFF0C\u8BA4\u4E3A\u552F\u6709\u4EB2\u8EAB\u7ECF\u5386\u6B32\u671B\u4E0E\u4E16\u4FD7\uFF0C\u624D\u80FD\u771F\u6B63\u8D85\u8D8A\u5B83\u3002

\u7B2C\u516D\u7AE0\uFF1A\u8F6E\u56DE\uFF08Samsara\uFF09
\u4E3B\u8981\u89C2\u70B9\uFF1A\u6089\u8FBE\u591A\u6C89\u6EBA\u4E8E\u8D22\u5BCC\u3001\u60C5\u6B32\u4E0E\u6743\u529B\uFF0C\u9010\u6E10\u8FF7\u5931\u81EA\u6211\uFF0C\u5185\u5FC3\u7A7A\u865A\u3002
\u91CD\u8981\u6BB5\u843D\uFF1A\u201C\u4ED6\u53D8\u5F97\u80A5\u80D6\u3001\u8F6F\u5F31\u3001\u602F\u61E6\u2026\u2026\u4ED6\u7684\u7075\u9B42\u50CF\u88AB\u5C18\u57C3\u8986\u76D6\u7684\u955C\u5B50\u3002\u201D
\u89E3\u8BFB\uFF1A\u4E16\u4FD7\u751F\u6D3B\u867D\u63D0\u4F9B\u77ED\u6682\u6B22\u6109\uFF0C\u5374\u65E0\u6CD5\u586B\u8865\u7CBE\u795E\u7A7A\u6D1E\u3002\u8F6E\u56DE\u4E0D\u4EC5\u662F\u4F5B\u6559\u6982\u5FF5\uFF0C\u4E5F\u8C61\u5F81\u4EBA\u5728\u7269\u8D28\u4E16\u754C\u4E2D\u7684\u8FF7\u5931\u3002

\u7B2C\u4E03\u7AE0\uFF1A\u5728\u6CB3\u8FB9
\u4E3B\u8981\u89C2\u70B9\uFF1A\u6089\u8FBE\u591A\u7EDD\u671B\u6B32\u81EA\u6740\uFF0C\u5374\u88AB\u201C\u5535\u201D\uFF08Om\uFF09\u7684\u795E\u5723\u97F3\u8282\u5524\u9192\uFF0C\u51B3\u5B9A\u91CD\u65B0\u5F00\u59CB\u3002
\u91CD\u8981\u6BB5\u843D\uFF1A\u201C\u5F53\u4ED6\u542C\u5230\u2018\u5535\u2019\u7684\u58F0\u97F3\uFF0C\u4ED6\u6C89\u7761\u7684\u7075\u9B42\u82CF\u9192\u4E86\u3002\u201D
\u89E3\u8BFB\uFF1A\u201C\u5535\u201D\u8C61\u5F81\u5B87\u5B99\u672C\u6E90\u4E0E\u7EDF\u4E00\u6027\u3002\u8FD9\u4E00\u523B\u6807\u5FD7\u7740\u6089\u8FBE\u591A\u4ECE\u6B7B\u4EA1\u8FB9\u7F18\u56DE\u5F52\u751F\u547D\uFF0C\u5F00\u542F\u65B0\u9636\u6BB5\u7684\u89C9\u609F\u3002

\u7B2C\u516B\u7AE0\uFF1A\u6E21\u8239\u592B\uFF08\u74E6\u82CF\u4EE3\u74E6\uFF09
\u4E3B\u8981\u89C2\u70B9\uFF1A\u6089\u8FBE\u591A\u8DDF\u968F\u8001\u8239\u592B\u74E6\u82CF\u4EE3\u74E6\u5B66\u4E60\u8046\u542C\u6CB3\u6C34\uFF0C\u9886\u609F\u4E07\u7269\u4E00\u4F53\u3001\u65F6\u95F4\u865A\u5E7B\u3002
\u91CD\u8981\u6BB5\u843D\uFF1A\u201C\u6CB3\u6C34\u540C\u65F6\u5B58\u5728\u4E8E\u6BCF\u4E00\u5904\uFF0C\u6E90\u5934\u4E0E\u5165\u6D77\u53E3\u3001\u8FC7\u53BB\u4E0E\u672A\u6765\uFF0C\u7686\u5728\u540C\u4E00\u65F6\u523B\u3002\u201D
\u89E3\u8BFB\uFF1A\u6CB3\u6C34\u6210\u4E3A\u201C\u9053\u201D\u7684\u8C61\u5F81\u2014\u2014\u6D41\u52A8\u3001\u5305\u5BB9\u3001\u65E0\u5206\u522B\u3002\u6089\u8FBE\u591A\u5F00\u59CB\u7406\u89E3\u201C\u5706\u878D\u7EDF\u4E00\u201D\u7684\u667A\u6167\u3002

\u7B2C\u4E5D\u7AE0\uFF1A\u513F\u5B50
\u4E3B\u8981\u89C2\u70B9\uFF1A\u6089\u8FBE\u591A\u4E0E\u5361\u739B\u62C9\u4E4B\u5B50\u6765\u5230\u6CB3\u8FB9\uFF0C\u4F46\u5C11\u5E74\u53DB\u9006\u79BB\u53BB\u3002\u6089\u8FBE\u591A\u4F53\u4F1A\u7236\u7231\u4E4B\u82E6\u3002
\u91CD\u8981\u6BB5\u843D\uFF1A\u201C\u4ED6\u7EC8\u4E8E\u660E\u767D\uFF0C\u4E3A\u4F55\u7236\u4EB2\u5F53\u5E74\u65E0\u6CD5\u7559\u4F4F\u4ED6\u2014\u2014\u7231\u5373\u662F\u653E\u624B\u3002\u201D
\u89E3\u8BFB\uFF1A\u901A\u8FC7\u5931\u53BB\u513F\u5B50\uFF0C\u6089\u8FBE\u591A\u5B8C\u6210\u5BF9\u201C\u6267\u8457\u201D\u7684\u6700\u540E\u653E\u4E0B\uFF0C\u7406\u89E3\u6148\u60B2\u4E0E\u65E0\u6761\u4EF6\u7684\u7231\u3002

\u7B2C\u5341\u7AE0\uFF1A\u74E6\u82CF\u4EE3\u74E6\u7684\u79BB\u53BB
\u4E3B\u8981\u89C2\u70B9\uFF1A\u74E6\u82CF\u4EE3\u74E6\u529F\u6210\u8EAB\u9000\uFF0C\u5C06\u6E21\u8239\u4EA4\u7ED9\u6089\u8FBE\u591A\uFF0C\u81EA\u5DF1\u878D\u5165\u5B87\u5B99\u3002
\u91CD\u8981\u6BB5\u843D\uFF1A\u201C\u4ED6\u8138\u4E0A\u95EA\u8000\u7740\u5B81\u9759\u7684\u5149\u8F89\uFF0C\u5982\u540C\u661F\u8FB0\u5F52\u4E8E\u591C\u7A7A\u3002\u201D
\u89E3\u8BFB\uFF1A\u771F\u6B63\u7684\u89C9\u609F\u8005\u4E0D\u5C45\u529F\u3001\u4E0D\u6267\u8457\u8EAB\u4EFD\uFF0C\u81EA\u7136\u6D88\u878D\u4E8E\u5927\u9053\u4E4B\u4E2D\u3002

\u7B2C\u5341\u4E00\u7AE0\uFF1A\u4E54\u6587\u8FBE
\u4E3B\u8981\u89C2\u70B9\uFF1A\u8001\u53CB\u4E54\u6587\u8FBE\u518D\u6B21\u6765\u8BBF\uFF0C\u6089\u8FBE\u591A\u5411\u4ED6\u63ED\u793A\u201C\u4E07\u7269\u7686\u5584\u201D\u201C\u7231\u5373\u771F\u7406\u201D\u7684\u7EC8\u6781\u9886\u609F\u3002
\u91CD\u8981\u6BB5\u843D\uFF1A\u201C\u4E16\u754C\u5E76\u975E\u4E0D\u5B8C\u7F8E\uFF0C\u4E5F\u4E0D\u662F\u8D70\u5728\u901A\u5F80\u5B8C\u7F8E\u7684\u8DEF\u4E0A\u2014\u2014\u5B83\u6BCF\u4E00\u523B\u90FD\u662F\u5B8C\u7F8E\u7684\u3002\u201D
\u201C\u6211\u4E0D\u518D\u5C06\u4E16\u754C\u4E0E\u6211\u6240\u671F\u5F85\u7684\u3001\u7406\u60F3\u5316\u7684\u4E16\u754C\u6BD4\u8F83\uFF0C\u800C\u662F\u63A5\u53D7\u5B83\uFF0C\u7231\u5B83\u3002\u201D
\u89E3\u8BFB\uFF1A\u8FD9\u662F\u5168\u4E66\u54F2\u5B66\u9AD8\u6F6E\u3002\u6089\u8FBE\u591A\u8D85\u8D8A\u4E8C\u5143\u5BF9\u7ACB\uFF08\u5584/\u6076\u3001\u5723/\u4FD7\uFF09\uFF0C\u8FBE\u5230\u201C\u5706\u89C9\u201D\u2014\u2014\u5728\u4E00\u5207\u4E2D\u770B\u89C1\u795E\u6027\u3002

\u7B2C\u5341\u4E8C\u7AE0\uFF08\u5C3E\u58F0\uFF09
\u4E3B\u8981\u89C2\u70B9\uFF1A\u4E54\u6587\u8FBE\u4EB2\u543B\u6089\u8FBE\u591A\u989D\u5934\uFF0C\u77AC\u95F4\u770B\u5230\u4E07\u5343\u4F17\u751F\u76F8\uFF0C\u6CEA\u6D41\u6EE1\u9762\u3002
\u91CD\u8981\u6BB5\u843D\uFF1A\u201C\u4ED6\u770B\u5230\u4E00\u4E2A\u4EBA\u7684\u8138\uFF0C\u53C8\u770B\u5230\u5343\u4E07\u5F20\u8138\u2026\u2026\u6240\u6709\u8FD9\u4E9B\u8138\u90FD\u5728\u4E0D\u65AD\u53D8\u5316\u3001\u91CD\u751F\u3001\u6B7B\u4EA1\uFF0C\u5374\u53C8\u6C38\u6052\u4E0D\u53D8\u3002\u201D
\u89E3\u8BFB\uFF1A\u4E2A\u4F53\u4E0E\u6574\u4F53\u5408\u4E00\uFF0C\u65F6\u95F4\u5E7B\u8C61\u7834\u9664\u3002\u89C9\u609F\u4E0D\u662F\u9003\u79BB\u4E16\u754C\uFF0C\u800C\u662F\u5728\u4E16\u754C\u4E2D\u770B\u89C1\u6C38\u6052\u3002

\u603B\u7ED3\u6838\u5FC3\u601D\u60F3\uFF1A
\u771F\u7406\u4E0D\u53EF\u8A00\u4F20\uFF0C\u5FC5\u987B\u4EB2\u8BC1\uFF1A\u6559\u4E49\u662F\u624B\u6307\uFF0C\u4E0D\u662F\u6708\u4EAE\u3002
\u7ECF\u5386\u5373\u4FEE\u884C\uFF1A\u82E6\u884C\u4E0E\u7EB5\u6B32\u7686\u662F\u9053\u8DEF\u7684\u4E00\u90E8\u5206\uFF0C\u5173\u952E\u5728\u4E8E\u201C\u5168\u7136\u4F53\u9A8C\u201D\u3002
